  class ipcam_soc_gpio_blk extends uvm_reg_block;
    `uvm_object_utils(ipcam_soc_gpio_blk)
    rand ipcam_soc_gpio_blk_id ID;
    rand ipcam_soc_gpio_blk_irq_status IRQ_STATUS;
